// Vendored from `@std/cli@1.0.32` (`unicode_width.ts`, `_run_length.ts`,
// `_data.json`); UNICODE_VERSION 15.0.0. Run-length-encoded base64 tables.
const TABLE_0_D = "AAECAwQFBgcICQoLDA0OAw8DDwkQCRESERIA";
const TABLE_0_R = "AQEBAgEBAQEBAQEBAQEBBwEHAVABBwcBBwF4";
const TABLE_1_D =
  "";
const TABLE_1_R =
  "";
const TABLE_2_D =
  "";
const TABLE_2_R =
  "";

function runLengthDecode({ d, r }: { d: string; r: string }): Uint8Array {
  const data = atob(d);
  const runLengths = atob(r);
  let out = "";

  for (const [i, ch] of [...runLengths].entries()) {
    out += data[i]!.repeat(ch.codePointAt(0)!);
  }

  return Uint8Array.from([...out].map((x) => x.codePointAt(0)!));
}

let tables: Uint8Array[] | null = null;

function lookupWidth(cp: number) {
  if (!tables) {
    tables = [
      { d: TABLE_0_D, r: TABLE_0_R },
      { d: TABLE_1_D, r: TABLE_1_R },
      { d: TABLE_2_D, r: TABLE_2_R },
    ].map(runLengthDecode);
  }

  const t1Offset = tables[0]![(cp >> 13) & 0xff]!;
  const t2Offset = tables[1]![128 * t1Offset + ((cp >> 6) & 0x7f)]!;
  const packedWidths = tables[2]![16 * t2Offset + ((cp >> 2) & 0xf)]!;

  const width = (packedWidths >> (2 * (cp & 0b11))) & 0b11;

  return width === 3 ? 1 : width;
}

const cache = new Map<string, number | null>();

function charWidth(char: string) {
  if (cache.has(char)) {
    return cache.get(char)!;
  }

  const codePoint = char.codePointAt(0)!;
  let width: number | null = null;

  if (codePoint < 0x7f) {
    width = codePoint >= 0x20 ? 1 : codePoint === 0 ? 0 : null;
  } else if (codePoint >= 0xa0) {
    width = lookupWidth(codePoint);
  } else {
    width = null;
  }

  cache.set(char, width);

  return width;
}

/** Terminal column width of `str`, summed per code point (East Asian Wide/Fullwidth count 2, controls 0). */
export function unicodeWidth(str: string): number {
  return [...str].map((ch) => charWidth(ch) ?? 0).reduce((a, b) => a + b, 0);
}
